\begin{align*} f(x+g(y))=2x+y\phantom{gx}&  \implies 2x+2g(y)-2g(0)=2x+y\phantom{gx}&   \implies\boxed{g(y)=\tfrac{y}{2}+g(0)}& \end{align*}
Now
